Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Reviews per week vs the typical (median) week of the same year. 1x = an ordinary week; darker = players suddenly talking more. Best with one game selected.",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "isValid(datum.reviews)"
    },
    {
      "calculate": "toDate(datum.date)",
      "as": "d"
    },
    {
      "calculate": "year(datum.d)",
      "as": "yr"
    },
    {
      "calculate": "min(52, toNumber(timeFormat(datum.d, ''%U'')))",
      "as": "wk"
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "reviews",
          "as": "reviews"
        },
        {
          "op": "sum",
          "field": "negative",
          "as": "negative"
        },
        {
          "op": "min",
          "field": "d",
          "as": "week_start"
        }
      ],
      "groupby": [
        "yr",
        "wk"
      ]
    },
    {
      "filter": "datum.reviews > 0"
    },
    {
      "calculate": "datum.negative / datum.reviews",
      "as": "neg_share"
    },
    {
      "calculate": "toDate(datum.week_start)",
      "as": "week_from"
    },
    {
      "joinaggregate": [
        {
          "op": "median",
          "field": "reviews",
          "as": "median_week"
        }
      ],
      "groupby": [
        "yr"
      ]
    },
    {
      "calculate": "max(1, datum.reviews / datum.median_week)",
      "as": "ratio"
    },
    {
      "calculate": "min(8, datum.ratio)",
      "as": "ratio_capped"
    }
  ],
  "mark": {
    "type": "rect",
    "cornerRadius": 1.5,
    "stroke": "#FFFFFF",
    "strokeWidth": 1
  },
  "encoding": {
    "x": {
      "field": "wk",
      "type": "ordinal",
      "title": null,
      "scale": {
        "domain": {
          "expr": "sequence(0, 53)"
        }
      },
      "axis": {
        "values": [
          0,
          4,
          9,
          13,
          17,
          22,
          26,
          30,
          35,
          39,
          43,
          48
        ],
        "labelExpr": "[''Jan'',''Feb'',''Mar'',''Apr'',''May'',''Jun'',''Jul'',''Aug'',''Sep'',''Oct'',''Nov'',''Dec''][indexof([0,4,9,13,17,22,26,30,35,39,43,48], datum.value)]",
        "labelAngle": 0,
        "domain": false,
        "ticks": false,
        "labelColor": "#5F6368",
        "labelAlign": "left"
      }
    },
    "y": {
      "field": "yr",
      "type": "ordinal",
      "title": null,
      "axis": {
        "domain": false,
        "ticks": false,
        "labelColor": "#1F2328",
        "labelPadding": 6
      }
    },
    "color": {
      "field": "ratio_capped",
      "type": "quantitative",
      "scale": {
        "type": "log",
        "domain": [
          1,
          8
        ],
        "range": [
          "#EEF1F5",
          "#8FA6BF",
          "#2E3F55"
        ],
        "interpolate": "rgb",
        "clamp": true
      },
      "legend": null
    },
    "tooltip": [
      {
        "field": "week_from",
        "type": "temporal",
        "title": "Week from",
        "format": "%d %b %Y"
      },
      {
        "field": "reviews",
        "title": "Reviews",
        "format": ","
      },
      {
        "field": "ratio",
        "title": "vs median week",
        "format": ".1f"
      },
      {
        "field": "neg_share",
        "title": "Negative share",
        "format": ".1%"
      }
    ]
  },
  "width": "container",
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "background": null
  },
  "height": "container"
}'
